\begin{table}
\begin{center}
\caption{Пример простой таблицы.}
<<CMD_111>>
\begin{tabular}{| c | c | c |}
\hline
Порядок & Произвольные коэффициенты & коэффициенты\\
фильтра & <<MATH_INLINE_86>> &   <<MATH_INLINE_87>> \\
